mapper.select:
SELECT EXISTS (
    SELECT 1 FROM document_import_task t
    JOIN document d ON d.id = t.document_id
    WHERE d.knowledge_base_id = #{kbId}
      AND (t.status IN ('PENDING', 'RUNNING') OR (t.status = 'FAILED' AND t.next_retry_at IS NOT NULL))
) OR EXISTS (
    SELECT 1 FROM chat_message m
    JOIN chat_conversation c ON c.id = m.conversation_id
    WHERE c.knowledge_base_id = #{kbId}
      AND m.role = 'ASSISTANT' AND m.status IN ('PROCESSING', 'CANCEL_REQUESTED')
)
